using System.Text.Json;

namespace Strata.Core.Content.Loading;

/// <summary>
/// The list of content files in deterministic load order. Generated by
/// <c>Strata.Tools manifest</c> (CI verifies it is up to date) so exported builds never need to
/// enumerate directories inside a .pck.
/// </summary>
public static class ContentManifest
{
    public sealed class Model
    {
        public string Format { get; set; } = "strata-content-manifest";
        public int Version { get; set; } = 1;
        public List<string> Files { get; set; } = new();
    }

    public static IReadOnlyList<string> Read(IDataSource source)
    {
        var model = JsonSerializer.Deserialize<Model>(source.ReadText(ContentLoader.ManifestPath), ContentJson.Options)
                    ?? throw new InvalidDataException("Empty manifest.");
        if (model.Format != "strata-content-manifest") throw new InvalidDataException($"Unexpected manifest format '{model.Format}'.");
        return model.Files;
    }

    /// <summary>Builds the manifest by scanning data/ (excluding data/reference, data/config and the manifest itself).</summary>
    public static Model Build(string dataDirectory)
    {
        var root = Path.GetFullPath(dataDirectory);
        var files = Directory.EnumerateFiles(root, "*.json", SearchOption.AllDirectories)
            .Select(f => Path.GetRelativePath(root, f).Replace('\\', '/'))
            .Where(f => !f.StartsWith("reference/", StringComparison.Ordinal) && !f.StartsWith("config/", StringComparison.Ordinal) && f != "manifest.json")
            .OrderBy(f => f.Count(c => c == '/'))
            .ThenBy(f => f, StringComparer.Ordinal)
            .ToList();
        return new Model { Files = files };
    }

    public static string Serialize(Model model) => JsonSerializer.Serialize(model, ContentJson.Options) + "\n";
}
